#!/usr/bin/env bash
# Render report/REPORT.md (generated by code/report.py) to report/REPORT.pdf.
# Needs pandoc (e.g. `pip install pypandoc_binary`, or set PANDOC) and a LaTeX with pdflatex.
set -euo pipefail
here="$(cd "$(dirname "$0")/.." && pwd)"
PANDOC="${PANDOC:-pandoc}"
cd "$here/report"
tail -n +2 REPORT.md | "$PANDOC" -o REPORT.pdf --resource-path=. \
  --from markdown-tex_math_dollars-raw_tex --pdf-engine=pdflatex \
  --include-in-header=pdf/header.tex --lua-filter=pdf/breakcode.lua \
  --toc --toc-depth=2 \
  -V documentclass=article -V papersize=a4 -V fontsize=10pt \
  -V geometry:margin=2cm -V colorlinks=true -V linkcolor=blue -V urlcolor=blue \
  -V fontfamily=XCharter -V monofont=inconsolata \
  -M title="Dense Tsetlin-machine segmentation: what helps, what does not" \
  -M date="$(date -r REPORT.md +%Y-%m-%d)"
echo "wrote $here/report/REPORT.pdf"
